// TransferReceipt defines model for TransferReceipt.
//
// It holds exactly one of the following variants:
//   - BlockchainTransfer (use AsBlockchainTransfer / NewTransferReceiptFromBlockchainTransfer)
//   - FiatTransfer (use AsFiatTransfer / NewTransferReceiptFromFiatTransfer)
type TransferReceipt struct{ union }

// AsBlockchainTransfer decodes the union as BlockchainTransfer.
func (u TransferReceipt) AsBlockchainTransfer() (BlockchainTransfer, error) {
	return unionAs[BlockchainTransfer](u.union)
}

// NewTransferReceiptFromBlockchainTransfer returns a TransferReceipt holding v.
func NewTransferReceiptFromBlockchainTransfer(v BlockchainTransfer) *TransferReceipt {
	return &TransferReceipt{newUnion(v)}
}

// AsFiatTransfer decodes the union as FiatTransfer.
func (u TransferReceipt) AsFiatTransfer() (FiatTransfer, error) {
	return unionAs[FiatTransfer](u.union)
}

// NewTransferReceiptFromFiatTransfer returns a TransferReceipt holding v.
func NewTransferReceiptFromFiatTransfer(v FiatTransfer) *TransferReceipt {
	return &TransferReceipt{newUnion(v)}
}

// Discriminator returns the value of the "type" property.
func (u TransferReceipt) Discriminator() (string, error) { return u.union.discriminator("type") }

// ValueByDiscriminator decodes the union into the variant selected by the "type" property.
func (u TransferReceipt) ValueByDiscriminator() (any, error) {
	d, err := u.Discriminator()
	if err != nil {
		return nil, err
	}
	switch d {
	case "BLOCKCHAIN":
		return u.AsBlockchainTransfer()
	case "FIAT":
		return u.AsFiatTransfer()
	}
	return nil, unknownDiscriminator("TransferReceipt", d)
}

